16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164, e.g. +61412345678")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private java.time.LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "namesake_count")
61	    private Integer namesakeCount;
62	
63	    @Column(name = "postcode")
64	    private String postcode;
65	
66	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
67	    private Set<Pet> pets;
68	
69	    public String getAddress() {
70	        return this.address;
71	    }
72	
73	    public void setAddress(String address) {
74	        this.address = address;
75	    }
76	
77	    public String getCity() {
78	        return this.city;
79	    }
80	
81	    public void setCity(String city) {
82	        this.city = city;
83	    }
84	
85	    public String getTelephone() {
86	        return this.telephone;
87	    }
88	
89	    public void setTelephone(String telephone) {
90	        this.telephone = telephone;
91	    }
92	
93	    public String getEmail() {
94	        return this.email;
95	    }
96	
97	    public void setEmail(String email) {
98	        this.email = email;
99	    }
100	
101	    public java.time.LocalDate getRegistrationDate() {
102	        return this.registrationDate;
103	    }
104	
105	    public void setRegistrationDate(java.time.LocalDate registrationDate) {
106	        this.registrationDate = registrationDate;
107	    }
108	
109	    /**
110	     * Stable identifier for the household an owner belongs to, derived from last name and
111	     * address. Owners who share a household (same last name and address) share this value.
112	     */
113	    @Transient
114	    public String getHouseholdId() {
115	        String key = (this.lastName + "|" + this.address).toLowerCase();
116	        return String.format("H-%08X", key.hashCode());
117	    }
118	
119	    public String getCustomerCode() {
120	        return this.customerCode;
121	    }
122	
123	    public void setCustomerCode(String customerCode) {
124	        this.customerCode = customerCode;
125	    }
126	
127	    public Integer getNamesakeCount() {
128	        return this.namesakeCount;
129	    }
130	
131	    public void setNamesakeCount(Integer namesakeCount) {
132	        this.namesakeCount = namesakeCount;
133	    }
134	
135	    public String getPostcode() {
136	        return this.postcode;
137	    }
138	
139	    public void setPostcode(String postcode) {
140	        this.postcode = postcode;
141	    }
142	
143	    protected Set<Pet> getPetsInternal() {
144	        if (this.pets == null) {
145	            this.pets = new HashSet<>();
146	        }
147	        return this.pets;
148	    }
149	
150	    protected void setPetsInternal(Set<Pet> pets) {
151	        this.pets = pets;
152	    }
153	
154	    public List<Pet> getPets() {
155	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
156	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
157	        return Collections.unmodifiableList(sortedPets);
158	    }
159	
160	    public void setPets(List<Pet> pets) {
161	        this.pets = new HashSet<>(pets);
162	    }
163	
164	    public void addPet(Pet pet) {
165	        getPetsInternal().add(pet);
166	        pet.setOwner(this);
167	    }
168	
169	    /**
170	     * Return the Pet with the given name, or null if none found for this Owner.
171	     *
172	     * @param name to test
173	     * @return true if pet name is already in use
174	     */
175	    public Pet getPet(String name) {
176	        return getPet(name, false);
177	    }
178	
179	    /**
180	     * Return the Pet with the given name, or null if none found for this Owner.
181	     *
182	     * @param name to test
183	     * @return true if pet name is already in use
184	     */
185	    public Pet getPet(String name, boolean ignoreNew) {
186	        name = name.toLowerCase();
187	        for (Pet pet : getPetsInternal()) {
188	            if (!ignoreNew || !pet.isNew()) {
189	                String compName = pet.getName();
190	                compName = compName.toLowerCase();
191	                if (compName.equals(name)) {
192	                    return pet;
193	                }
194	            }
195	        }
196	        return null;
197	    }
198	
199	    public Pet getPet(Integer petId) {
200	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
201	    }
202	
203	    @Override
204	    public String toString() {
205	        return new ToStringCreator(this)
206	
207	            .append("id", this.getId())
208	            .append("new", this.isNew())
209	            .append("lastName", this.getLastName())
210	            .append("firstName", this.getFirstName())
211	            .append("address", this.address)
212	            .append("city", this.city)
213	            .append("telephone", this.telephone)
214	            .toString();
215	    }
216	}
