1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	import java.time.temporal.TemporalAdjusters;
6	import java.util.List;
7	
8	import net.officefloor.plugin.variable.Out;
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.mapper.OwnerMapper;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	import org.springframework.samples.petclinic.rest.escalation.MissingFieldsException;
14	
15	public class BuildOwner {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built)
18	            throws MissingFieldsException {
19	        Owner owner = ownerMapper.toOwner(request);
20	        LocalDate supplied = owner.getRegistrationDate();
21	        if (supplied != null && supplied.isAfter(LocalDate.now())) { // future date: reject as 400
22	            throw new MissingFieldsException(List.of("registrationDate"));
23	        }
24	        LocalDate date = supplied != null ? supplied : LocalDate.now();
25	        if (date.getDayOfWeek().getValue() > 5) { // Saturday or Sunday: roll forward to Monday
26	            date = date.with(TemporalAdjusters.next(DayOfWeek.MONDAY));
27	        }
28	        owner.setRegistrationDate(date);
29	        built.set(owner);
30	    }
31	}
