15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
23	    @Mapping(target = "membershipLevel", expression = "java(org.springframework.samples.petclinic.rest.function.owner.MembershipLevel.of(owner))")
24	    @Mapping(target = "locality", expression = "java(owner.getCustomerCode().substring(0, owner.getCustomerCode().indexOf('-')))")
25	    @Mapping(target = "contactPreference", expression = "java((owner.getEmail() != null && !owner.getEmail().isBlank()) ? \"EMAIL\" : \"PHONE\")")
26	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.rest.function.owner.IdentityKey.of(owner))")
27	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.rest.function.owner.CheckDigit.of(owner))")
28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    Owner toOwner(OwnerDto ownerDto);
31	
32	    @Mapping(target = "id", ignore = true)
33	    @Mapping(target = "pets", ignore = true)
34	    Owner toOwner(OwnerFieldsDto ownerDto);
35	
36	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
37	
38	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
39	
40	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
41	        OwnerPageDto ownerPageDto = new OwnerPageDto();
42	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
43	        ownerPageDto.setPage(ownerPage.getNumber());
44	        ownerPageDto.setSize(ownerPage.getSize());
45	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
46	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
47	        return ownerPageDto;
48	    }
49	}
