1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Bulk-signup rule: an owner carries a warning once more than {@value #WARN_THRESHOLD} owners share
10	 * its registration day, matching the accumulation the daily-limit rule counts.
11	 */
12	public final class BulkSignup {
13	
14	    private static final int WARN_THRESHOLD = 80;
15	
16	    private BulkSignup() {
17	    }
18	
19	    public static boolean warned(Owner owner, OwnerRepository ownerRepository) {
20	        LocalDate day = owner.getRegistrationDate();
21	        long registeredThatDay = ownerRepository.findAll().stream()
22	            .filter(existing -> day.equals(existing.getRegistrationDate()))
23	            .count();
24	        return registeredThatDay > WARN_THRESHOLD;
25	    }
26	}
